insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('wos-hosdn-do-fiaran-fetzn-au', 'Wos hosdn do fiaran Fetzn au?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was hast du den da für einen Fetzen an?', '[{"kategorie": "wörtlich", "text": "\"Was hast du denn da für ein zerschlissenes Stück Stoff an?\"  2. Was trägst du denn da für einen alten Lumpen?  3. Was hast du denn da für einen Schlabberlook an?"}]'::jsonb, ''),
  ('dea-hod-lauta-fetzn-im-zeignis', 'Dea hod lauta Fetzn im Zeignis!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der hat lauter Fetzen im Zeugnis!', '[{"kategorie": "wörtlich", "text": "\"Der hat lauter Fünfer im Zeugnis!\"  2. Der hat im Zeugnis überall nur Fünfer stehen!  3. Der hat fast nur Fünfer im Zeugnis!"}]'::jsonb, ''),
  ('so-an-fetzn-von-an-schuss-muassd-amoi-hoidn', 'So an Fetzn von an Schuss muassd amoi hoidn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So einen Fetzen von einem Schuss musst du einmal halten!', '[{"kategorie": "wörtlich", "text": "\"So einen Mordsschuss musst du erst mal halten!\"  2. So eine Granate musst du erst mal abwehren!  3. So einen Hammer-Schuss musst du erst mal rausdrehen!"}]'::jsonb, ''),
  ('zu-so-an-fetzn-schdeig-i-ned-ins-bett', 'Zu so an Fetzn schdeig I ned ins Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zu so einem Fetzen steige ich nicht ins Bett!', '[{"kategorie": "wörtlich", "text": "\"Zu so einem Lotterweib steige ich nicht ins Bett!\"  2. Mit so einer verluderten Schlampe lege ich mich nicht ins Bett!  3. Mit so einem vergammelten Luder gehe ich nicht ins Bett!"}]'::jsonb, ''),
  ('gestan-hob-i-a-so-an-muadsfetzn-ghobd-dass-i-ned-min-taxi-sondan-min-nootoazd-haamkumma-bin', 'Gestan hob I a so an Muadsfetzn ghobd, dass I ned min Taxi, sondan min Nootoazd haamkumma bin!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gestern habe ich einen einen derartigen Mordsfetzen gehabt, dass ich nicht mit dem Taxi, sondern mit dem Notarzt heimgekommen bin!', '[{"kategorie": "wörtlich", "text": "\"Gestern hatte ich einen einen derartigen Mordsrausch, dass ich nicht mit dem Taxi, sondern mit dem Notarzt heimgekommen bin!\"  2. Gestern war ich so besoffen, dass ich statt dem Taxi gleich die Rettung nehmen musste!  3. Gestern hatte ich einen derartigen Vollrausch, dass mich der [[Saani]] heimgebracht hat – inklusive [[Speibsackerl]]!"}]'::jsonb, ''),
  ('so-a-muadsrausch-is-nix-wods-deina-leewa-winschn-daedst', 'So a Muadsrausch is nix, wods deina Leewa winschn dädst!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'So ein Mordsrausch ist nichts, was du deiner Leber wünschen tätest!', '[{"kategorie": "wörtlich", "text": "\"So ein Mordsrausch ist nichts, was du deiner Leber wünschen würdest!\"  2. Für so einen Mordsrausch müsste man sich bei seiner Leber eigentlich entschuldigen!  3. Leberfreundlich ist so ein Mordsrausch leider nicht! (sioehe auch [[Muadsrausch]])"}]'::jsonb, ''),
  ('noch-so-ana-muadsfettn-leegsd-di-niida-und-brauchsd-a-wochn-ualaub', 'Noch so ana Muadsfettn leegsd di niida und brauchsd a Wochn Ualaub!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach so einer Mordsfetten legst dich nieder und brauchst eine Woche Urlaub!', '[{"kategorie": "wörtlich", "text": "\"Nach so einem Mordsrausch legst du dich nieder und brauchst eine Woche Urlaub!\"  2. Nach so einem Vollrausch liegst du da wie ein nasser Sack und brauchst eine ganze Woche, bis du wieder richtig auf die Beine kommst!  3. Der Rausch war so gewaltig, dass ich Erholung auf Krankenschein beantragt hab!"}]'::jsonb, ''),
  ('i-hob-an-fetzn', 'I hob an Fetzn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe einen Fetzen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe einen Rausch!\"  2. Ich habe einen sitzen!  3. Ich bin im [[Öl]]!  4. Ich bin in der [[Fetten]]!"}]'::jsonb, ''),
  ('friara-hauma-mit-an-fetznlaawal-aum-parkplotz-gschbueued-und-de-goi-woan-unsare-jackn', 'Friara hauma mit an Fetznlaawal aum Parkplotz gschbüüd - und de Goi woan unsare Jackn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Früher haben wir mit einem Fetzenlaberl am Parkplatz gespielt - und die Tore waren unsere Jacken!', '[{"kategorie": "wörtlich", "text": "\"Früher haben wir mit einem selbstgenähten Stofffußball am Parkplatz gespielt - und die Tore waren unsere Jacken!\"  2. Als Kinder haben wir mit einem selbstgebastelten Stoffball auf dem Parkplatz gekickt – und unsere Jacken dienten als Tore!  3. Früher spielten wir mit einem selbstgenähten Fußball aus alten Fetzen – die Tore: zwei Jacken auf dem Asphalt!"}]'::jsonb, ''),
  ('bevua-ma-uns-an-echtn-leedaboin-haum-leistn-kenna-haumma-imma-min-guatn-oidn-fetznboin-gschbueued', 'Bevua ma uns an echtn Leedaboin haum leistn kenna, haumma imma min guatn, oidn Fetznboin gschbüüd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Bevor wir uns einen echten Lederball haben leisten können, haben wir immer mit dem guten, alten Fetzenball gespielt!', '[{"kategorie": "wörtlich", "text": "\"Bevor wir uns einen richtigen Lederball leisten konnten, spielten wir immer mit unserem selbstgemachten Stoffball!\"  2. Ein echter Fußball war Luxus – also spielten wir mit einem zusammengenähten Stoffball, lange bevor ein Lederball in Reichweite war!  3. Bis wir einen echten Lederball hatten, hat uns der gute, alte Fetzenball vollkommen gereicht!"}]'::jsonb, ''),
  ('a-fetznschaeaedl-wia-du-soitad-an-hoeoem-troong-und-a-leichtschueued-oobndrauf-ochtung-trottl-im-aunflug', 'A Fetznschäädl wia du soitad an Hööm troong - und a Leichtschüüd oobndrauf: ''Ochtung, Trottl im Aunflug!''', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ein Fetzenschädel wie du sollte einen Helm tragen - und ein Leuchtschild obendrauf: ''Achtung, Trottel im Anflug!', '[{"kategorie": "wörtlich", "text": "\"Ein Rauschkopf wie du sollte einen Helm tragen - und ein Leuchtschild obendrauf: ''Achtung, Trottel im Anflug!\"  2. So ein Volltrottel wie du sollte mit ''nem Helm rumlaufen – und einem Blinkpfeil obendrauf: ''Dummheit in Bewegung!''  3. Für so einen Fetzenschädel wie dich müsste Helmpflicht gelten - plus Warnschild obendrauf: ''Resthirn wurde evakuiert!"}]'::jsonb, ''),
  ('da-fetzntandla-hod-de-oidn-klaadln-fia-zwaa-kreiza-mitgnumma-und-aan-toog-schbaeaeda-aum-noschmoakd-ums-doppaede-vakaufd', 'Da Fetzntandla hod de oidn Klaadln fia zwaa Kreiza mitgnumma und aan Toog schbääda aum Noschmoakd ums Doppäde vakaufd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Fetzentandler hat die alten Kleider für zwei Kreuzer mitgenommen und tags darauf am Naschmarkt ums Doppelte verkauft!', '[{"kategorie": "wörtlich", "text": "\"Der Altwarenhändler nahm die alten Kleider für zwei Kreuzer mit und verkaufte sie tags darauf am Naschmarkt um das Doppelte!\"  2. Der Lumpenhändler erstand die abgetragenen Kleider für zwei Kreuzer und verkaufte sie tags darauf am Naschmarkt ums Doppelte!  3. Die alten Kleidungsstücke gingen für zwei Kreuzer an den Tandler – am nächsten Tag wechselten sie am Naschmarkt für das Doppelte den Besitzer!"}]'::jsonb, ''),
  ('des-fraeulein-von-hohenberg-hod-si-jedn-toog-im-fiaka-zua-oopa-bringan-lossn-imma-zua-soeoebn-uazeit', 'Des Fräulein von Hohenberg hod si jedn Toog im Fiaka zua Oopa bringan lossn - imma zua sööbn Uazeit!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Das Fräulein von Hohenberg hat sich jeden Tag im Fiaker zur Oper bringen lassen, immer zur selben Uhrzeit!', '[{"kategorie": "wörtlich", "text": "\"Fräulein von Hohenberg ließ sich im Fiaker täglich zur Oper bringen, stets zur selben Uhrzeit!\"  2. Tag für Tag ließ sich Fräulein von Hohenberg im Fiaker zur Oper kutschieren – stets zur gleichen Stunde!  3. Pünktlich wie der Uhrschlag der Hofburg bestieg Fräulein von Hohenberg tagtäglich ihren Fiaker, um sich zur Oper fahren zu lassen!"}]'::jsonb, ''),
  ('a-wiina-fiaka-brauchd-ka-navi-dea-kennd-jedn-pflostaschdaa-beim-vuanauman', 'A Wiina Fiaka brauchd ka Navi - dea kennd jedn Pflostaschdaa beim Vuanauman!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein Wiener Fiaker braucht kein Navi - der kennt jeden Pflasterstein beim Vornamen!', '[{"kategorie": "wörtlich", "text": "\"Ein Wiener Kutscher braucht keine Navigationshilfe - der kennt jeden Pflasterstein beim Vornamen!\"  2. Ein echter Fiaker findet sich in Wien blind zurecht – der könnte die Stadt auch rückwärts im Schlaf fahren!  3. Ein Wiener Fiaker hat das Stadtbild im Blut – jeder Pflasterstein ist für ihn ein alter Bekannter!"}]'::jsonb, ''),
  ('da-fiakaboi-woara-mischung-aus-oopanboi-und-hausmaastaboi-mit-de-schdrizzis-im-frack-und-de-fiakafraeulein-im-ausbuagdn-seidnklaadl', 'Da Fiakaboi woara Mischung aus Oopanboi und Hausmaastaboi - mit de Schdrizzis im Frack und de Fiakafräulein im ausbuagdn Seidnklaadl!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Fiakerball war eine Mischung aus Opernball und Hausmeisterball – mit den Strizzis im Frack und den Fiakerfräuleins im geborgten Seidenkleid!', '[{"kategorie": "wörtlich", "text": "\"Der Fiakerball war eine Mischung aus Opernball und Hausmeisterball – mit den Zuhältern im Frack und den leichten Mädchen im geborgten Seidenkleid!\"  2. Der Fiakerball war das einzige gesellschaftliche Event, wo ein Kutscher neben einem Grafen tanzte – und keiner hat’s komisch gefunden!  3. Der Fiakerball vereinte den Prunk des Hofes mit dem rauen Charme der Vorstadt – ein Tanzfest zwischen zwei Welten!"}]'::jsonb, ''),
  ('kaum-a-liadl-dazoeoed-vom-wiina-oitoog-mit-so-vueue-schmaeae-und-heaz-wias-fiakaliad', 'Kaum a Liadl dazööd vom Wiina Oitoog mit so vüü Schmää und Heaz wias Fiakaliad!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Kaum ein Lied erzählt vom Wiener Alltag mit so viel Schmäh und Herz wie das Fiakerlied!', '[{"kategorie": "wörtlich", "text": "\"Kaum ein Lied erzählt den Wiener Alltag mit so viel Schmäh und Herz wie das Fiakerlied!\"  2. Kaum ein Lied fängt die Wiener Seele so feinfühlig und augenzwinkernd ein wie das Fiakerlied!  3. Das Fiakerlied trägt das Herz der Stadt auf der Zunge – mit Schmäh, Schmerz und einem Augenzwinkern!"}]'::jsonb, ''),
  ('fiaka-milli', 'Fiaka-Milli', 'die', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Fiaker-Milli', '[{"kategorie": "hist.", "text": "Künstlername der Wiener Volkssängerin Emilie Turecek (1846-1889)"}, {"kategorie": "", "text": "Volksliebling der Wiener, \"Venus von Wien\" (ihre humorvoll-frivolen Darbietungen von [[Fiaker-Gstanzeln]], die das Wiener Volksleben und die Fiaker thematisierten, waren ebenso berühmt wie berüchtigt.  In den Polizeiakten wurde sie als Prostituierte geführt, doch dies tat ihrer Beliebtheit als freizügige Sängerin und Schauspielerin, die stets in erotisch-engem Fiaker-Outfit auftrat, keinen Abbruch. Ihre unzähligen Verehrer bedachten sie vielmehr mit dem liebevollen Titel \"Venus von Wien\")"}]'::jsonb, ''),
  ('de-fiaka-milli-woa-ka-heiliche-owa-auf-da-bueuene-hods-an-jeedn-heirichn-in-an-konzeatsoi-vawaundld', 'De Fiaka-Milli woa ka Heiliche - owa auf da Büüne hods an jeedn Heirichn in an Konzeatsoi vawaundld!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Fiaker-Milli war keine Heilige – aber auf der Bühne hat sie jeden Heurigen in einen Konzertsaal verwandelt!', '[{"kategorie": "wörtlich", "text": "\"Die Fiaker-Milli war kein Kind von Traurigkeit – aber wenn sie auf der Bühne zu singen begann, war’s ein heiliger Moment im Vorstadtwirtshaus!\"  2. Die Fiaker-Milli war ein Bühnenphänomen – mit einer Stimme, die selbst den Lärm der Schank zum Verstummen brachte!  3. Die Fiaker-Milli war eine Muse aus der Vorstadt – keine Heilige, aber mit einer göttlichen Stimme!"}]'::jsonb, ''),
  ('fisoin-soitad-ma-ned-zlaung-kochn-sunst-valians-d-foab-und-de-vitamin', 'Fisoin soitad ma ned zlaung kochn, sunst valians d''Foab und de Vitamin!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Fisolen sollten nicht zu lange gekocht werden, sonst verlieren sie ihre Farbe und Vitamine!', '[{"kategorie": "wörtlich", "text": "\"Fisolen dürfen nicht zu lange gekocht werden, da sie sonst ihre Farbe und Nährstoffe einbüßen!\"  2. Wenn man Fisolen zu lange kocht, verlieren sie ihre frische Farbe und wertvolle Vitamine!  3. Fisolen sollten nur kurz gegart werden, um Farbe und Vitamingehalt zu bewahren!"}]'::jsonb, ''),
  ('ziag-deine-fisoin-ei', 'Ziag deine Fisoin ei!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ziehe deine Fisolen ein!', '[{"kategorie": "wörtlich", "text": "\"Zieh deine Latschen ein!\"  2. Zieh deine Füße ein!  3. Mach die Beine weg!  4. Zieh die [[Haxen]] ein!"}]'::jsonb, ''),
  ('fixlaudon-no-amoi', 'Fixlaudon no amoi!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Fixlaudon noch einmal!', '[{"kategorie": "allg.", "text": "\"Zum Teufel noch einmal!\"  3. Verdammt noch mal!  4. Verdammt und zugenäht!  5. Verflucht!  6. [[Kruzitiakn]]!  7. [[Fix]] Gramadanzn!"}]'::jsonb, ''),
  ('fix-laudon', 'Fix Laudon!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Fix Laudon!', '[{"kategorie": "allg.", "text": "\"Zum Teufel noch einmal!\"  3. Verdammt noch mal!  4. Verdammt und zugenäht!  5. Verflucht!  6. [[Kruzitiakn]]!  7. [[Fix]] Gramadanzn!"}]'::jsonb, ''),
  ('mia-haums-mei-haendi-gflaadad', 'Mia haums mei Händi gflaadad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir haben sie mein Handy gefladert!', '[{"kategorie": "wörtlich", "text": "\"Mir haben sie mein Handy geklaut!\"  2. Jemand hat mein Mobiltelefon mitgehen lassen!  3. Mir wurde mein Handy gestohlen!  4. (Deutschland): \"Mein Handy wurde gemopst!\""}]'::jsonb, ''),
  ('wia-haum-an-flaadarantn-in-da-fiama-jeedn-toog-foeoen-hundad-euro-in-da-kassa', 'Wia haum an Flaadarantn in da Fiama - jeedn Toog föön hundad Euro in da Kassa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir haben einen Fladeranten in der Firma - jeden Tag fehlen 100 Euro in der Kassa!', '[{"kategorie": "wörtlich", "text": "\"Wir haben einen Dieb in der Firma – Tag für Tag verschwinden 100 Euro aus der Kassa!\"  2. Da treibt sich ein richtiger Langfinger in der Firma herum – aus der Kassa sind jeden Tag 100 Euro futsch!  3. Bei uns schleicht ein Fladerant durch die Firma – täglich sind 100 Euro weg aus der Kassa!"}]'::jsonb, ''),
  ('endlich-haums-den-flaadara-dawischd-dea-denan-leidln-in-da-bim-s-goeoed-ausn-taschl-ziagd', 'Endlich haums den Flaadara dawischd, dea denan Leidln in da Bim s''Gööd ausn Taschl ziagd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Endlich haben sie diesen Fladerer erwischt, der den Leuten in der Bim das Geld aus dem Taschl zieht!', '[{"kategorie": "wörtlich", "text": "\"Jetzt haben sie endlich den Langfinger erwischt, der den Leuten in der Straßenbahn das Geld aus der Tasche zieht!\"  2. Endlich haben sie den Taschendieb geschnappt, der den Leuten in der Straßenbahn dauernd das Geld aus den Taschen klaut!  3. Den Fladerer, der die Leute in der Straßenbahn bestiehlt, wurde nun endlich eingelocht!"}]'::jsonb, ''),
  ('oida-des-breedl-is-a-waunsinn-de-flaadan-schaud-aus-wia-gmoind', 'Oida, des Breedl is a Waunsinn - de Flaadan schaud aus wia gmoind!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Alter, das Brett ist ein Wahnsinn – die Fladern schaut aus wie gemalt!', '[{"kategorie": "wörtlich", "text": "\"Mann, das Brett ist ein Wahnsinn – die Fladerung sieht aus wie gemalt!\"  2. Alter, schau dir das Brett an – die Maserung ist ja der absolute Wahnsinn!  3. So eine saubere Fladerung - da brauchst du keinen Lack – die lebt ganz für sich!"}]'::jsonb, ''),
  ('bei-dem-dahaam-is-so-schdaubig-dassd-noocha-de-flankaln-im-hois-pickn-host', 'Bei dem dahaam is so schdaubig, dassd noocha de Flankaln im Hois pickn host!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei dem daheim ist es so staubig, dass du nachher die Flankerln im Hals picken hast!', '[{"kategorie": "wörtlich", "text": "\"Bei ihm zu Hause ist es so staubig, dass man die Staubpartikel noch Stunden später im Hals kleben hat!\"  2. \"Bei dem Typen daheim ist es so staubig, dass einem die Staubfutzerln nachher regelrecht im Hals kleben!\"  3. \"Der Staub in seiner Wohnung ist so dicht, dass sich die Flankerln nachher im Hals festsetzen!\""}]'::jsonb, ''),
  ('des-haundtiachl-flankald', 'Des Haundtiachl flankald!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Handtuch flankerlt!', '[{"kategorie": "wörtlich", "text": "\"Das Handtuch fusselt!\"  2. Das Handtuch verliert Fasern!  3. Das Handtuch franst aus!"}]'::jsonb, ''),
  ('draussn-flankalds-a-bissl', 'Draussn flankalds a bissl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Draußen flankerlt es ein bisschen!', '[{"kategorie": "wörtlich", "text": "\"Draußen rieselt leicht der Schnee!\"  2. Draußen herrscht leichtes Schneerieseln!  3. Draußen tanzen sanft die Schneeflöckchen!"}]'::jsonb, ''),
  ('kaa-witz-drei-schnaeaeflankal-und-de-leit-foan-wia-waunns-a-schnaeaeschduam-waarad', 'Kaa Witz: Drei Schnääflankal und de Leit foan, wia waunns a Schnääschduam waarad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kein Witz: Drei Schneeflankerl und die Leute fahren, wie wenn es ein Schneesturm wäre!', '[{"kategorie": "wörtlich", "text": "\"Echt jetzt – kaum fallen drei Schneeflöckchen, fahren die Leute so langsam , als wär’s ein Schneesturm!\"  2. Also wirklich - ein paar Schneeflöckchen in der Luft, und schon fahren die Leute wie auf rohen Eiern!  3. Ein paar Schneeflöckchen genügen, und die Leute fahren plötzlich nur noch im Zeitlupentempo!"}]'::jsonb, ''),
  ('imma-nochn-auhaazn-taunzn-klaane-ruassflankaln-duach-de-koide-wintaluft', 'Imma nochn Auhaazn taunzn klaane Ruassflankaln duach de koide Wintaluft!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Immer nach dem Anheizen tanzen kleine Russflankerln durch die kalte Winterluft!', '[{"kategorie": "wörtlich", "text": "\"Immer nach dem Anheizen schweben kleine Russflöckchen durch die frostige Winterluft!\"  2. Kaum ist der Ofen an, steigen feine Rußpartikel auf und tanzen im Winterwind!  3. Nach jedem Anheizen wirbeln dunkle Flöckchen durch die kalte Morgenluft!"}]'::jsonb, ''),
  ('i-putz-wisch-saug-und-am-naechstn-toog-pickn-scho-wiida-iwaroi-de-schdaubflankaln', 'I putz, wisch, saug - und am nächstn Toog pickn scho wiida iwaroi de Schdaubflankaln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich putze, wische, sauge – und am nächsten Tag picken schon wieder überall die Staubflöckchen!', '[{"kategorie": "wörtlich", "text": "\"Ich putze, wische, sauge – und trotzdem kleben am nächsten Tag schon wieder überall die Staubflöckchen!\"  2. Ich putze, wische, sauge – und trotzdem ist am nächsten Tag wieder alles voll mit Staubfusselchen!  3. Hausarbeit ist ein endloser Kreislauf – kaum geputzt, sind die Staubflöckchen alle wieder da!"}]'::jsonb, ''),
  ('untam-bett-is-a-gaunza-zoo-aus-schdaubfuuzaln-de-haum-si-sogoa-schoo-gsichda-wochsn-lossn', 'Untam Bett is a gaunza Zoo aus Schdaubfuuzaln - de haum si sogoa schoo Gsichda wochsn lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Unter’m Bett ist ein ganzer Zoo aus Staubfuzerln - die haben sich sogar schon G’sichter wachsen lassen!', '[{"kategorie": "wörtlich", "text": "\"Unter dem Bett ist ein ganzer Zoo aus Staubfusselchen - die haben sich sogar schon Gesichter wachsen lassen!\"  2. Unter meinem Bett haben die Staubfusselchen schon angefangen, sich Gesichter zu zeichnen!  3. Unterm Bett wimmelt es nur so von Staubfusselchen – die könnten schon Namen haben!"}]'::jsonb, ''),
  ('noch-an-toog-im-woipulli-pickn-ma-de-woifuuzaln-an-oin-eckn-und-endn', 'Noch an Toog im Woipulli pickn ma de Woifuuzaln an oin Eckn und Endn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach einem Tag im Wollpulli picken mir die Wollfuzerln an allen Ecken und Enden!', '[{"kategorie": "wörtlich", "text": "\"Nach einem Tag im Wollpulli kleben mir die Wollfusselchen an allen Ecken und Enden!\"  2. Ich brauch nur einen Tag Wolle zu tragen, und schon kleben mir die Wollfusselchen überall am Körper!  3. Nach einem Tag im Wollpulli haften die Wollfusselchen an mir wie an einem wandelnden Wollknäuel!"}]'::jsonb, ''),
  ('i-woid-ma-nua-a-poa-woiflankaln-vom-pulli-zupfn-auf-amoi-woa-do-a-loch', 'I woid ma nua a poa Woiflankaln vom Pulli zupfn - auf amoi woa do a Loch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich wollte mir nur ein paar Wollflankerln vom Pulli zupfen - auf einmal war da ein Loch!', '[{"kategorie": "wörtlich", "text": "\"Ich wollte mir nur ein paar Wollflöckchen vom Pulli zupfen - aber auf einmal war da ein Loch!\"  2. Ich hab nur ein paar Wollfusselchen vom Pulli gezupft – plötzlich war da ein Loch!  3. Beim Versuch, ein paar Wollflöckchen zu entfernen, hab ich mir ein Loch in meinen Pulli gerissen!"}]'::jsonb, ''),
  ('da-fleck-auf-mein-hemad-is-kunst-modeane-kunst', 'Da Fleck auf mein Hemad is Kunst - modeane Kunst!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Fleck auf meinem Hemd ist Kunst - moderne Kunst!', '[{"kategorie": "wörtlich", "text": "\"Der Klecks auf meinem Hemd ist Kunst - moderne Kunst!\"  2. Der Klecks auf meinem Hemd ist kein Fleck - das ist abstrakte Kunst!  3. Der Fleck auf meinem Hemd ist ''Fashion für Fortgeschrittene'' – i nenn’s „Wiener Impressionismus!“"}]'::jsonb, ''),
  ('mit-drei-fleck-im-zeignis-wiast-a-extrarundn-draan-miassn', 'Mit drei Fleck im Zeignis wiast a Extrarundn draan miassn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mit drei Fleck im Zeugnis wirst du eine Extrarunde drehen müssen!', '[{"kategorie": "wörtlich", "text": "\"Mit drei Fünfern im Zeugnis wirst du eine Ehrenrunde drehen müssen!\"  2. Mit drei Nicht Genügend im Zeugnis wirst du das Schuljahr wohl wiederholen müssen!  3. Mit drei Fleck im Zeugnis bleibst unweigerlich sitzen und musst die Klasse wiederholen!"}]'::jsonb, ''),
  ('waunn-da-koeoena-in-fleck-aussehoid-haassts-zoin', 'Waunn da Kööna in Fleck aussehoid, haassts zoin!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der Kellner den Fleck rausholt, heißt es ''Zahlen''!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Kellner die Geldbörse hervorholt, ist es Zeit zu bezahlen!\"  2. Wenn der Kellner die Geldtasche zückt, geht es ans Zahlen!  3. Wenn der Kellner den Geldbeutel rauszieht, heißt es ''Ran an die Scheine!''"}]'::jsonb, ''),
  ('i-hob-eam-an-fleck-geem-und-dea-doodl-is-aa-no-re-gaungan', 'I hob eam an Fleck geem, und dea Doodl is aa no ''Re'' gaungan!', '', '', '', 'Wiener Kartentipplerjargon', 'Ich hab ihm einen Fleck gegeben, und dieser Dodel ist auch noch ''Re'' gegangen!', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Ich hab ihm Kontra gegeben, und dieser Schwachkopf ist auch noch ''Re'' gegangen!\"  2. Ich hab einen Kontra angesagt – und der Depp geht ernsthaft noch Re!  3. Ich habe kontriert, und dieser Vollkoffer hat daraufhin auch noch ''Re'' gesagt!"}]'::jsonb, ''),
  ('ea-hod-ma-zwaa-fleck-aum-tisch-gleegd-ungfroogd-sauwa-und-in-bar', 'Ea hod ma zwaa Fleck aum Tisch gleegd - ungfroogd, sauwa und in bar!', '', '', '', 'Wiener Gaunersprache', 'Er hat mir zwei Fleck auf den Tisch gelegt – ungefragt, sauber und in bar!', '[{"kategorie": "wörtlich", "text": "\"Er hat mir zwei Fünfhunderteuroscheine auf den Tisch gelegt – ungefragt, sauber und in bar!\"  2. Er hat mir zwei Fünfhunderter hingelegt – kommentarlos, bar auf die Hand!  3. Er hat mir zwei große Scheine auf den Tisch gelegt - ohne ein Wort, direkt und cash!"}]'::jsonb, ''),
  ('a-gschdaundane-flecksuppn-rasiad-da-in-moong', 'A gschdaundane Flecksuppn rasiad da in Moong!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine gestandene Flecksuppe rasiert dir den Magen!', '[{"kategorie": "wörtlich", "text": "\"Eine deftige Flecksuppe putzt dir den Magen so richtig durch!\"  2. Eine echte Flecksuppe geht runter wie Lava und räumt alles weg, was im Weg ist!  3. Eine richtig starke Flecksuppe zertrümmert sogar Gallensteine!"}]'::jsonb, ''),
  ('fleckd-wia-da-deifae-schmeckd-wia-da-himmae-de-peafekte-lasaan', 'Fleckd wia da Deifä, schmeckd wia da Himmä - de peafekte Lasaan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Fleckt wie der Teufel, schmeckt wie der Himmel – die perfekte Lasagne!', '[{"kategorie": "wörtlich", "text": "\"Macht teuflische Flecken, schmeckt aber himmlisch – die perfekte Lasagne!\"  2. Saugt sich durchs Leiberl, brennt sich ins Hirn – Lasagne vom Feinsten!  3. Die perfekte Lasagne - wos’d nachher ausschaust wie g’stochen, aber grinst wie frisch verliebt!"}]'::jsonb, ''),
  ('des-fleckd', 'Des fleckd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das fleckt!', '[{"kategorie": "wörtlich", "text": "\"Das haut hin!\"  2. Das klappt!  3. Das läuft wie geschmiert!"}]'::jsonb, ''),
  ('dea-fleckd-auf-vadochd-egal-wosa-fiara-blaadl-hod', 'Dea fleckd auf Vadochd - egal, wosa fiara Blaadl hod!', '', '', '', 'Wiener Kartentipplerjargon', 'Der fleckt auf Verdacht - egal, was er für ein Blatt hat!', '[{"kategorie": "wörtlich", "text": "\"Der kontriert auf Verdacht - egal, was er für ein Blatt in der Hand hält!\"  2. Der haut einen Kontra raus, noch bevor er überhaupt seine Karten sortiert hat!  3. Der sagt einen Kontra an, wie andere Leute „Guten Tag“ sagen!"}]'::jsonb, ''),
  ('do-is-voi-wiar-in-aana-sardinanbixn-kaa-fleckal-mea-plotz', 'Do is voi wiar in aana Sardinanbixn - kaa Fleckal mea Plotz!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da ist es voll wie in einer Sardinenbüchse - kein Fleckerl mehr Platz!', '[{"kategorie": "wörtlich", "text": "\"Da ist es gerammelt voll bis obenhin – kein Fleckchen mehr Platz!\"  2. \"Hier ist es zum Bersten voll - kein einziges freies Plätzchen!\"  3. \"Die Hütte platzt aus allen Nähten - nicht einmal ein Eckerl ist hier noch frei!\""}]'::jsonb, ''),
  ('jojo-nuara-klaans-fleckal-soogda-dabei-schauds-tischtuach-aus-wia-nooch-an-schlochtfest', 'Jojo, nuara klaans Fleckal, soogda - dabei schauds Tischtuach aus wia nooch an Schlochtfest!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Jaja, nur a kleines Fleckerl, sagt er – dabei schaut das Tischtuch aus wie nach ''nem Schlachtfest!', '[{"kategorie": "wörtlich", "text": "\"Jaja, nur a kleines Fleckchen, sagt er – dabei schaut das Tischtuch aus wie nach ''nem Schlachtfest!\"  2. Nur ein kleines Fleckerl? Nein, das ist ein Tatort, und der Hauptverdächtige sitzt mit’m Löffel im Mund am Tisch!  3. „Nur a kleiner Patzer“, sagt er - dabei schaut der Tisch aus wie nach ’nem Kannibalen-Brunch!"}]'::jsonb, ''),
  ('leeg-in-da-sekundn-drei-fleckal-aum-tisch-oda-i-polia-da-de-goschn-dassd-in-grissbaam-doppaed-siichsd', 'Leeg in da Sekundn drei Fleckal aum Tisch - oda I polia da de Goschn, dassd in Grissbaam doppäd siichsd!', '', '', '', 'Wiener Gaunersprache', 'Leg in der Sekunde drei Fleckerln auf den Tisch - oder ich polier dir die Goschen, dass du den Weihnachtsbaum doppelt siehst!', '[{"kategorie": "wörtlich", "text": "\"Leg in der Sekunde drei große Scheine auf den Tisch - oder ich schlag dir die Fresse ein, dass du den Weihnachtsbaum doppelt siehst!\"  2. Leg sofort drei Lappen auf den Tisch - sonst liegst du in der Sekunde mit Kieferbruch unterm Tisch!  3. Leg das Geld aufn Tisch – sonst leg ich dich drunter!"}]'::jsonb, ''),
  ('de-fleckaln-wean-im-soizwossa-bissfest-kochd', 'De Fleckaln wean im Soizwossa bissfest kochd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Fleckerln werden im Salzwasser bissfest gekocht!', '[{"kategorie": "wörtlich", "text": "\"Die Fleckerln werden in Salzwasser al dente gegart!\"  2. \"Man kocht die Fleckerln in gesalzenem Wasser, bis sie bissfest sind!\"  3. \"Die Fleckerln werden in kochendem Salzwasser gargezogen!\""}]'::jsonb, ''),
  ('krautfleckaln-a-unschlogboare-kombi-aus-buttawaachn-kraut-und-bissfestn-fleckaln', 'Krautfleckaln - a unschlogboare Kombi aus buttawaachn Kraut und bissfestn Fleckaln!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Krautfleckerln - eine unschlagbare Kombi aus butterweichem Kraut und bissfesten Fleckerln!', '[{"kategorie": "wörtlich", "text": "\"Krautfleckerln - eine unschlagbare Kombi aus butterweichem Weißkraut und bissfesten Teigfleckchen!\"  2. Krautfleckerln – zart geschmortes Weißkraut trifft auf perfekt gegarte Teigfleckerl!  3. Krautfleckerln - ein Klassiker der Wiener Küche, bei dem Textur und Geschmack perfekt zusammenspielen!"}]'::jsonb, ''),
  ('goidbraun-iwaboochane-schinknfleckaln-mit-raam-und-muskat-a-traum-ausn-oofn', 'Goidbraun iwaboochane Schinknfleckaln mit Raam und Muskat - a Traum ausn Oofn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Goldbraun überbackene Schinkenfleckerl mit Rahm und Muskat – ein Traum aus dem Ofen!', '[{"kategorie": "wörtlich", "text": "\"Knusprig überbackene Schinkenfleckerl mit feinem Rahmguss und einem Hauch Muskat – Ofenglück pur!\"  2. Feinwürzige Schinkenfleckerl mit cremigem Rahm und Muskat – frisch gebacken, unwiderstehlich gut!  3. Zart gratinierte Teigfleckchen mit Schinkenstücken, Rahm und Muskat – ein Klassiker der Wiener Küche!"}]'::jsonb, ''),
  ('a-fleckalboodschn-is-wia-da-eigane-oide-unbequem-wiads-easchd-waunna-foeoed', 'A Fleckalboodschn is wia da eigane Oide - unbequem wiads easchd, waunna fööd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Fleckerlpatschen ist wie der eigene Alte – unbequem wird''s erst, wenn er fehlt!', '[{"kategorie": "wörtlich", "text": "\"Ein Flickenpantoffel ist wie ein langjähriger Partner – unbequem wird''s erst, wenn er fehlt!\"  2. Flickenpantoffel sind wie eine langjährige Ehe: warm, ausgeleiert, aber irgendwie heimelig!  3. Ein alter Fleckerlpatschen und ein treuer Partner haben eines gemeinsam: Man merkt ihren Wert erst, wenn sie weg sind!"}]'::jsonb, ''),
  ('fleckaldaeaewich-waassd-ee-des-is-des-zu-wos-de-leit-heit-boho-style-soong', 'Fleckaldääwich? Waassd ee, des is des, zu wos de Leit heit ''Boho Style'' soong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Fleckerlteppich? Weißt eh, das ist das, wozu die Leut heut „Boho-Style“ sagen!', '[{"kategorie": "wörtlich", "text": "\"Flickenteppich? Weißt eh, das ist das, was die Leute heute „Boho-Style“ nennen!\"  2. \"Ein bunter Fleckerlteppich am Boden? Trendiger Boho-Chic, sagt man heut!\"  3. Früher war ein Flickenteppich Ramsch, heut ist er ein Vintage-Statement - eh klar, Boho-Style halt!"}]'::jsonb, ''),
  ('vueue-plotz-host-beim-foschingsgschnaas-ned-owa-a-biadecklwoiza-geed-si-imma-noo-aus', 'Vüü Plotz host beim Foschingsgschnaas ned - owa a Biadecklwoiza geed si imma noo aus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Viel Platz hast du beim Faschingsgschnas nicht - aber ein Bierdeckelwalzer geht sich immer aus!', '[{"kategorie": "wörtlich", "text": "\"Beim Faschingsgschnas hast du nie mehr als 1m² Platz zum Tanzen - aber ein Bierdeckelwalzer geht sich allemal aus!\"  2. Am Kostümball tanzt man auf enstem Raum - aber ein [[Fleckerlwalzer]] ist für jeden drin!  3. Am Faschingsball zählt nicht die Fläche - 1m² fürn Bierdeckelwalzer reicht allemal aus!"}]'::jsonb, ''),
  ('vueue-plotz-host-aum-oopanboi-ned-owa-a-fleckalwoiza-geed-si-imma-aus', 'Vüü Plotz host aum Oopanboi ned - owa a Fleckalwoiza geed si imma aus!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Viel Platz hast du am Opernball nicht - aber ein Fleckerlwalzer geht sich immer aus!', '[{"kategorie": "wörtlich", "text": "\"Beim Opernball hast du nie mehr als 1m² Platz zum Tanzen - aber ein Fleckerlwalzer geht sich allemal aus!\"  2. Am Opernball tanzt man auf enstem Raum - aber ein Fleckerlwalzer ist für jeden drin!  3. Am Opernball zählt nicht die Fläche - 1m² fürn Fleckerlwalzer reicht allemal aus!"}]'::jsonb, ''),
  ('de-neiche-regelung-is-nix-ois-a-fleckaldaeaewich', 'De neiche Regelung is nix ois a Fleckaldääwich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die neue Regelung ist nichts als ein Fleckerlteppich!', '[{"kategorie": "wörtlich", "text": "\"Die neue Regelung ist nichts als ein Flickenteppich!\"  2. Die neue Regelung ist nichts als Stückwerk!  3. Die neue Regelung ist bloß eine halbgare Lösung!"}]'::jsonb, ''),
  ('leichsd-ma-an-kilo', 'Leichsd ma an Kilo?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Leihst du mir einen Kilo?', '[{"kategorie": "wörtlich", "text": "\"Leihst du mir einen Hunderter?\"  2. Kannst du mir 100 Euro leihen?  3. Kannst du mir einen Hunderter pumpen?"}]'::jsonb, ''),
  ('de-reiwa-haum-braundgschotzd-und-gfleddad', 'De Reiwa haum braundgschotzd und gfleddad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Räuber haben brandgeschatzt und gefleddert!', '[{"kategorie": "wörtlich", "text": "\"Die Räuber haben alles abgefackelt und leergeräumt!\"  2. Die Räuber zogen brandschatzend durchs Dorf und plünderten es bis auf den letzten Löffel aus!  3. Die Räuber zogen brandschatzend und marodierend durchs Land!"}]'::jsonb, ''),
  ('de-pest-woa-kaum-vuabei-do-san-scho-de-leichnfleddara-kumman-und-haum-in-de-massngraeaeba-noch-hobsoelichkeidn-gsuachd', 'De Pest woa kaum vuabei, do san scho de Leichnfleddara kumman - und haum in de Massngrääba noch Hobsölichkeidn gsuachd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Pest war kaum vorbei, da kamen die Leichenfledderer – und suchten in den Massengräbern nach Habseligkeiten!', '[{"kategorie": "wörtlich", "text": "\"Die Pest war kaum vorüber, da kamen die Leichenplünderer – und suchten in den Massengräbern nach Habseligkeiten!\"  2. Kaum war die Pest vorbei, da krochen die Aasgeier aus ihren Löchern – auf Beutezug durch die Leichenhaufen!  3. Was die Pest übrig ließ, wurde von den Leichenfledderern geholt - sie raubten alles, was noch glänzte!"}]'::jsonb, ''),
  ('froog-in-leichnfleddara-oba-fia-freidoog-no-a-kistn-frei-hod', 'Froog in Leichnfleddara, oba fia Freidoog no a Kistn frei hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Frag den Leichenfledderer, ob er für Freitag noch eine Kiste frei hat!', '[{"kategorie": "wörtlich", "text": "\"Frag den Leichenbestatter, ob er für Freitag noch einen Sarg frei hat!\"  2. (scherzhaft für): \"Frag den Kistenschubser, ob er Freitag noch wen unterbringen kann!\"  3. Frag den Fledderer vom Friedhof, ob er am Freitag noch einen Platz in der Erd’ hat!"}]'::jsonb, ''),
  ('meine-biacha-schdaub-i-heit-no-min-oidn-fleedawisch-von-da-omi-oo-so-wia-de-leit-im-barock', 'Meine Biacha schdaub I heit no min oidn Fleedawisch von da Omi oo - so wia de Leit im Barock!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Meine Bücher staube ich heute noch mit Omis altem Flederwisch ab - so wie die Leute im Barock!', '[{"kategorie": "wörtlich", "text": "\"Ich wische meine Bücher immer noch mit Großmutters altem Federwisch ab – ganz wie im Barock!\"  2. Zum Abstauben meiner Bücher benutze ich immer noch Omas alten Flederwisch – ein echter Klassiker aus barocken Zeiten!  3. Noch heute entstaube ich meine Bücher mit Großmutters altem Flederwisch – gleich einem Hausknecht der Barockzeit!"}]'::jsonb, ''),
  ('unsa-klaana-fleedawisch-bringd-uandlich-leebm-ind-buude', 'Unsa klaana Fleedawisch bringd uandlich Leebm ind Buude!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Unser kleiner Flederwisch bringt ordentlich Leben in die Bude!', '[{"kategorie": "wörtlich", "text": "\"Unser kleiner Wirbelwind bringt ordentlich Leben in die Bude!\"  2. Mit dem kleinen Energiebündel ist bei uns zu Hause immer was los!  3. Unser aufgeweckter Nachwuchs sorgt stets für fröhliches Treiben in der Bude!"}]'::jsonb, ''),
  ('amoi-fluudawusch-imma-fluudawusch-dea-hoits-nii-laung-bei-aana-aus', 'Amoi Fluudawusch, imma Fluudawusch - dea hoits nii laung bei aana aus!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Einmal Fluderwusch, immer Fluderwusch - der hält''s nie lang bei einer aus!', '[{"kategorie": "wörtlich", "text": "\"Einmal Hallodri, immer Hallodri - der hält''s nie lang bei einer aus!\"  2. Einmal Luftikus, immer Luftikus – der ist treu wie ein Straßenkater!  3. Ein Dauerflitzer in Sachen Liebe – der kriegt bei keiner die Hufe still!"}]'::jsonb, ''),
  ('a-gfueue-wiara-fleischhockahund-haum', 'a Gfüü wiara Fleischhockahund haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Gefühl wie ein Fleischhackerhund haben', '[{"kategorie": "wörtlich", "text": "\"herzlos wie ein Metzgerhund sein\""}, {"kategorie": "", "text": "\"kalt wie eine Hundeschnauze sein\""}, {"kategorie": "", "text": "\"einfühlsam wie ein Kettenhund sein\""}]'::jsonb, ''),
  ('dea-hod-a-gfueue-wiara-fleischhockahund-waunn-dea-laut-boeoed-gfriada-s-bluad-ei', 'Dea hod a Gfüü wiara Fleischhockahund - waunn dea laut bööd, gfriada s''Bluad ei!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat ein Gefühl wie ein Fleischhackerhund - wenn der laut bellt, gefriert dir das Blut!', '[{"kategorie": "wörtlich", "text": "\"Der wütet wie ein Metzgerhund - wenn der laut bellt, gefriert dir das Blut!\"  2. Der hat die Empathie von ''ner Motorsäge – wenn der loslegt, zieht’s dir die Socken aus!  3. Der bellt dich an wie ein Metzgerhund - da läuft dir das Blut rückwärts!"}]'::jsonb, ''),
  ('beim-fleischhocka-schdinkts-noch-bluat-schweiss-und-schweinsfett-owa-sei-wuaschd-ist-goettlich', 'Beim Fleischhocka schdinkts noch Bluat, Schweiss und Schweinsfett - owa sei Wuaschd ist göttlich!', '', '', '', 'Wiener Fleischhauer-Slang', 'Beim Fleischhacker stinkt’s nach Blut, Schweiß und Schweinefett – aber seine Wurst ist göttlich!', '[{"kategorie": "wörtlich", "text": "\"Beim Metzger stinkt’s nach Blut, Schweiß und altem Schweinefett – aber die Wurst ist göttlich!\"  2. Beim Fleischhauer riecht es streng nach Blut, Schweiß und Schweinefett –  aber seine Wurst ist einfach unschlagbar!  3. Beim Fleischer riecht’s wie in einem Schlachthaus, aber die Wurst ist so gut, da vergisst man alles andere!"}]'::jsonb, ''),
  ('unsa-fleischhaua-hockda-ollas-wos-via-fiass-hod', 'Unsa Fleischhaua hockda ollas, wos via Fiass hod!', '', '', '', 'Wiener Fleischhauer-Slang', 'Unser Fleischhauer hackt dir alles, was vier Füß hat!', '[{"kategorie": "wörtlich", "text": "\"Unser Metzger zerlegt dir alles, was vier Füße hat!\"  2. Unser Fleischhacker verarbeitet alles, was ''Grunz'', ‘Mäh’ oder ‘Muh’ sagt!  3. Ob Schwein, Lamm oder Rind - bei unserem Fleischer landet alles im Wolf, was vier Beine hat!"}]'::jsonb, ''),
  ('reib-ume-in-fliida', 'Reib ume in Fliida!', '', '', '', 'Wiener Gaunersprache', 'Reibe rüber den Flieder!', '[{"kategorie": "wörtlich", "text": "\"Gib her das Geld!\"  2. Schieb rüber die [[Marie]]!  3. Rück raus die Kohle!  4. [[Hea]] min Geaschdl!"}]'::jsonb, ''),
  ('hea-min-geaschdl', 'Hea min Geaschdl!', '', '', '', 'Wiener Gaunersprache', 'Her mit dem Gerstel!', '[{"kategorie": "wörtlich", "text": "\"Gib her das Geld!\"  2. Schieb rüber die [[Marie]]!  3. Rück raus die Kohle!  4. [[Reib]] ume in Flieda!"}]'::jsonb, ''),
  ('min-restalkohol-im-schaeaedl-und-da-sunn-im-gsichd-hob-i-nua-noo-zwinzld-und-auf-a-wunda-ghoffd', 'Min Restalkohol im Schäädl und da Sunn im Gsichd hob I nua noo zwinzld und auf a Wunda ghoffd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Mit dem Restalkohol im Kopf und der Sonne im Gesicht hab ich nur noch gezwinselt und auf ein Wunder gehofft!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Restalkohol im Kopf und der Sonne im Gesicht hab ich nur noch geblinzelt und auf ein Wunder gehofft!\"  2. Mein Schädel hat gebrummt, die Sonne hat gebrannt – da hab ich meine Augenlider nur noch reflexartig zugeklappt!  3. Mit dem halben Rausch noch im Schädel und der Sonne im Gesicht hab ich geblinzelt wie ein geschlagener Truthahn!"}]'::jsonb, ''),
  ('kaan-zwinzla-mochn', 'kaan Zwinzla mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Zwinzler machen', '[{"kategorie": "wörtlich", "text": "\"keinen Blinzler machen\""}, {"kategorie": "", "text": "\"keine Miene verziehen\""}, {"kategorie": "", "text": "\"nicht einmal mit der Wimper zucken\""}, {"kategorie": "", "text": "\"steif wie ein Laternenmast bleiben, ohne auch nur einmal zu zucken\""}]'::jsonb, 'Ea hod eam de Puffn auns Hian ghoidn, owa da Peitschalbua hod kaan Zwinzla gmochd!'),
  ('ea-hod-eam-de-puffn-auns-hian-ghoidn-owa-da-peitschalbua-hod-kaan-zwinzla-gmochd', 'Ea hod eam de Puffn auns Hian ghoidn, owa da Peitschalbua hod kaan Zwinzla gmochd!', '', '', '', 'Wiener Gaunersprache', 'Er hat ihm die Waffe ans Hirn gehalten, aber der Peitscherlbub hat keinen Zwinzler gemacht!', '[{"kategorie": "wörtlich", "text": "\"Er hat ihm die Waffe an die Schläfe gehalten, aber der Zuhälterjunge hat nicht einmal gezuckt!\"  2. Er drückte ihm die Pistole an den Kopf – doch der Zuhälterjunge blieb steif wie ein Laternenmast, ohne auch nur einmal zu zucken!  3. Der Lauf der Pistole lag wie ein kalter Finger an seiner Schläfe – doch der Zuhälterjunge zuckte nicht einmal mit der Wimper!"}]'::jsonb, 'kaan Zwinzla mochn'),
  ('es-woa-saukoid-owa-da-schnaeae-hod-so-schee-gflinsld-dass-an-fost-woam-wuan-is', 'Es woa saukoid, owa da Schnää hod so schee gflinsld, dass an fost woam wuan is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Es war saukalt, aber der Schnee hat so schön geflinselt, dass einem fast warm geworden ist!', '[{"kategorie": "wörtlich", "text": "\"Es war bitterkalt, aber der Schnee glitzerte so schön, dass einem fast warm wurde!\"  2. Es war saukalt, aber wie ich das Glitzern vom Schnee gesehen hab, ist mir richtig warm ums Herz geworden!  3. Es war eiskalt, aber der Schnee hat so schön gefunkelt, dass man beinah den Frost vergessen hätt!"}]'::jsonb, ''),
  ('hea-auf-zflinsln-wiara-aachkatzl-mit-aungschoodn', 'Hea auf z’flinsln wiara Aachkatzl mit Aungschoodn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hör auf zu flinseln wie ein Eichkatzl mit Augenschaden!', '[{"kategorie": "wörtlich", "text": "\"Hör auf zu blinzeln wie ein Eichkätzchen mit Augenschaden!\"  2. Du kneifst die Augen zusammen, als würde dir grad jemand mit der Taschenlampe ins Hirn leuchten!  3. Hör auf mit den Augen zu zucken wie ein Eichhörnchen unter Lichtschock! 8"}]'::jsonb, ''),
  ('friara-hod-a-echta-untawoeoedla-hundate-noabn-im-gsicht-ghobd-heit-reichd-a-aanzigs-flinsal-im-uawaschl', 'Friara hod a echta Untawöödla hundate Noabn im Gsicht ghobd - heit reichd a aanzigs Flinsal im Uawaschl!', '', '', '', 'Wiener Gaunersprache', 'Früher hat ein echter Unterweltler hunderte Narben im Gesicht gehabt - heute reicht ein einziges Flinserl im Ohrwaschl!', '[{"kategorie": "wörtlich", "text": "\"Früher hat ein echter Gangster hunderte Narben im Gesicht gehabt - heute reicht ein einziges Glitzersteinchen im Ohr!\"  2. Damals trugen Gangster ihre Geschichte im Gesicht – heut reichte ein einziger goldener Ohrstecker fürs Image!  3. Der Gangster von früher? Narben, Faustrecht und Schweigen. Der von heute? Ein Flinserl und ein Selfie!"}]'::jsonb, ''),
  ('friara-hod-a-echta-untawoeoedla-hundate-noabn-im-gsicht-ghobd-heit-reichd-a-aanzigs-linsal-im-uawaschl', 'Friara hod a echta Untawöödla hundate Noabn im Gsicht ghobd - heit reichd a aanzigs Linsal im Uawaschl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Früher hat ein echter Unterweltler hunderte Narben im Gesicht gehabt - heute reicht ein einziges Linserl im Ohrwaschl!', '[{"kategorie": "wörtlich", "text": "\"Früher hat ein echter Gangster hunderte Narben im Gesicht gehabt - heute reicht ein einziges Glitzersteinchen im Ohr!\"  2. Damals trugen Gangster ihre Geschichte im Gesicht – heut reichte ein einziger goldener Ohrstecker fürs Image!  3. Der Gangster von früher? Narben, Faustrecht und Schweigen. Der von heute? Ein Linserl und ein Selfie!"}]'::jsonb, ''),
  ('des-flitschal-haud-si-an-jeedn-zuwe-dea-no-hoibwegs-schdee-kau', 'Des Flitschal haud si an jeedn zuwe, dea no hoibwegs schdee kau!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieses Flitscherl schmeisst sich an jeden ran, der noch halbwegs stehen kann!', '[{"kategorie": "wörtlich", "text": "\"Dieses Flittchen schmeisst sich an jeden ran, der noch halbwegs stehen kann!\"  2. Dieses Billigluder springt auf alles, was warm und männlich ist!  3. So ''ne Tussi – kaum steht einer, liegt sie schon drunter!"}]'::jsonb, ''),
  ('de-flitschn-haud-si-an-jeedn-zuwe-dea-no-hoibwegs-schdee-kau', 'De Flitschn haud si an jeedn zuwe, dea no hoibwegs schdee kau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Diese Flitschen schmeisst sich an jeden ran, der noch halbwegs stehen kann!', '[{"kategorie": "wörtlich", "text": "\"Dieses Flittchen schmeisst sich an jeden ran, der noch halbwegs stehen kann!\"  2. Dieses Billigluder springt auf alles, was warm und männlich ist!  3. So ''ne Tussi – kaum steht einer, liegt sie schon drunter!"}]'::jsonb, ''),
  ('a-bissl-a-schoklaad-a-nylonschdrumpf-und-de-dollaflitschn-hod-si-scho-hiigleegd', 'A bissl a Schoklaad, a Nylonschdrumpf - und de Dollaflitschn hod si scho hiigleegd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein bisschen Schokolade, ein Nylonstrumpf – und das Dollarluder hat sich schon hingelegt!', '[{"kategorie": "wörtlich", "text": "\"Ein bisschen Schokolade, ein Nylonstrumpf – und das Ami-Liebchen lag schon flach!\"  2. Ein Schokoriegel, ein Paar Nylons – und schon war die Ami-Braut bettbereit!  3. Besatzungsromantik à la 1945: ein bisschen Schoki, ein Nylonstrumpf – und zack, Beine breit für die Siegermacht!"}]'::jsonb, ''),
  ('da-fogosch-vom-neisiidla-see-woa-aufn-punkt-gegoad-aussn-knusprig-innan-zoat', 'Da Fogosch vom Neisiidla See woa aufn Punkt gegoad - aussn knusprig, innan zoat!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Fogosch vom Neusiedler See war auf den Punkt gegart – außen knusprig, innen zart!', '[{"kategorie": "wörtlich", "text": "\"Der Zander aus dem Neusiedler See war perfekt gegart – mit krosser Haut und butterzartem Fleisch!\"  2. Ein exzellent zubereiteter Fogosch aus dem neusiedler See – außen goldbraun gebraten, innen herrlich saftig!  3. Der Zander aus dem Neusiedler See war ein Gedicht: knusprige Kruste, zartschmelzender Kern!"}]'::jsonb, ''),
  ('zwischn-fichtn-und-fean-samma-in-finstan-beagwoid-auffegwaundad', 'Zwischn Fichtn und Fean samma in finstan Beagwoid auffegwaundad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zwischen Fichten und Föhren sind wir den finsteren Bergwald hinaufgewandert!', '[{"kategorie": "wörtlich", "text": "\"Zwischen Fichten und Kiefern sind wir den dunklen Bergwald hochgewandert!\"  2. Zwischen hohen Nadelbäumen wanderten wir still den dunklen Berghang hinauf!  3. Umrahmt von Fichten und Föhren schlängelte sich unser Pfad durch den schweigsamen Bergwald nach oben!"}]'::jsonb, ''),
  ('an-fotz-zaan', 'an Fotz zaan', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Fotz ziehen', '[{"kategorie": "wörtlich", "text": "\"eine Grimasse schneiden\""}, {"kategorie": "", "text": "den Mund verziehen"}, {"kategorie": "", "text": "einen Schmollmund machen"}, {"kategorie": "Deutschland", "text": "\"eine Schnute ziehen\""}]'::jsonb, 'Waunn de ian Wüün ned kriagd, zaads glei an Fotz!'),
  ('waunn-de-ian-wueuen-ned-kriagd-zaads-glei-an-fotz', 'Waunn de ian Wüün ned kriagd, zaads glei an Fotz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn die ihren Willen nicht kriegt, zieht sie gleich einen Fotz!', '[{"kategorie": "wörtlich, Deutschland", "text": "\"Wenn sie nicht bekommt, was sie will, zieht sie gleich eine Schnute!\"  2. Sobald nicht alle nach ihrer Pfeife tanzen, schneidet sie ein Gesicht wie sieben Tage Regenwetter!  3.Wenn sie ihren Willen nicht bekommt, schaut sie gleich wie eine beleidigte Leberwurst!"}]'::jsonb, 'an Fotz zaan'),
  ('si-aum-fotz-draufschdeing', 'si aum Fotz draufschdeing', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich auf den Fotz draufsteigen', '[{"kategorie": "wörtlich", "text": "\"ein Schnäuzchen ziehen\""}, {"kategorie": "", "text": "den Mund griesgrämig verziehen"}, {"kategorie": "", "text": "eine beleidigte Miene aufsetzen"}]'::jsonb, 'Du brauchsda goa ned so aum Fotz draufschdeing- es woa jo nuara Schmää!'),
  ('du-brauchsda-goa-ned-so-aum-fotz-draufschdeing-es-woa-jo-nuara-schmaeae', 'Du brauchsda goa ned so aum Fotz draufschdeing- es woa jo nuara Schmää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du brauchst dir gar nicht so auf den Fotz draufzusteigen – es war doch nur ein Schmäh!', '[{"kategorie": "wörtlich", "text": "\"Du brauchst gar nicht so griesgrämig den Mund verziehen – das war doch bloß ein Scherz!\"  2. Jetzt zieh nicht gleich so ein Gesicht – das war doch nur Spaß!  3. Mensch, schmoll doch nicht gleich – das war ja nicht ernst gemeint!"}]'::jsonb, 'si aum Fotz draufschdeing'),
  ('in-fotz-haengan-lossn', 'in Fotz hängan lossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Fotz hängen lassen', '[{"kategorie": "wörtlich", "text": "\"die Mundwinkel hängen lassen\""}, {"kategorie": "fig.", "text": "\"den Kopf hängen lassen\""}, {"kategorie": "", "text": "eine betrübte Miene aufsetzen"}, {"kategorie": "", "text": "trübe Lippen machen"}, {"kategorie": "Deutschland", "text": "\"eine Schnute ziehen\""}]'::jsonb, 'Loss in Fotz ned hängan - muang is aa no a Toog!'),
  ('loss-in-fotz-ned-haengan-muang-is-aa-no-a-toog', 'Loss in Fotz ned hängan - muang is aa no a Toog!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Lass den Fotz nicht hängen - morgen ist auch noch ein Tag!', '[{"kategorie": "wörtlich", "text": "\"Lass den Kopf nicht hängen - morgen ist auch noch ein Tag!\"  2. Zieh nicht so ein Gesicht – das Leben geht weiter!  3. Komm schon, schmoll nicht – der nächste Tag bringt neue Chancen!"}]'::jsonb, 'in Fotz hängan lossn'),
  ('schneid-ned-so-an-fotz', 'Schneid ned so an Fotz!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Schneide nicht so einen Fotz!', '[{"kategorie": "wörtlich", "text": "\"Mach nicht so ein Gesicht!\"  2. Verzieh nicht so griesgrämig den Mund!  3. Hör auf, das Gesicht so lang zu ziehen!  4. (Deutschland): \"Zieh nicht so eine Schnute!\""}]'::jsonb, ''),
  ('do-mochd-sogoa-s-oaschal-an-fotz', 'Do mochd sogoa ''s Oaschal an Fotz!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da macht sogar das Arscherl einen Fotz!', '[{"kategorie": "wörtlich", "text": "\"Da setzt sogar der Hintern eine angewiderte Miene auf! \" 2. (Deutschland): \"Da zieht sogar der Hintern eine Schnute!\"  3. Da macht sogar das Ärschchen ein beleidigtes Gesicht!  4. Da schaut selbst der Allerwerteste beleidigt!"}]'::jsonb, ''),
  ('wem-fotzn', 'wem fotzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden fotzen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine Fotzenschelle verpassen\""}, {"kategorie": "", "text": "jemanden links und rechts ohrfeigen, [[abwatschen]], [[abflaschen]]"}, {"kategorie": "", "text": "jemandem eine [[antauchen]], [[auflegen]], [[umhängen]]"}]'::jsonb, 'Waunna uns vapfeifd, fotz i eam, bis eam de Waadln vibrian!'),
  ('waunna-uns-vapfeifd-fotz-i-eam-bis-eam-de-waadln-vibrian', 'Waunna uns vapfeifd, fotz i eam, bis eam de Waadln vibrian!', '', '', '', 'Wiener Gaunersprache', 'Wenn er uns verpfeift, fotz'' ich ihn, bis ihm die Wadln vibrieren!', '[{"kategorie": "wörtlich", "text": "\"Wenn er uns verpfeift, watsche ich ihn links-rechts, bis ihm die Waden vibrieren!\"  2. Wenn der uns verratzt, gibt''s solange Fotzn, bis er sein eigenes Gebiss ausspuckt!  3. Wenn er uns verpetzt, kriegt er von mir eine derartige Fotzn, dass noch seine Urenkel rote Wangen haben werden!"}]'::jsonb, 'wem fotzn'),
  ('dea-hod-si-a-uandliche-fotzn-eigfaungan', 'Dea hod si a uandliche Fotzn eigfaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat sich eine ordentliche Fotze eingefangen!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich eine gehörige Fotzenschelle eingefangen!\"  2. Der hat eine heftige Ohrfeige abkassiert!  3. Der hat eine gewaltige Dachtel eingeschenkt bekommen!"}]'::jsonb, ''),
  ('dea-trottl-postet-sei-diabsguad-im-fotznbiachl-und-wundad-si-warum-de-kiiwara-vua-da-tia-schdee', 'Dea Trottl postet sei Diabsguad im Fotznbiachl - und wundad si, warum de Kiiwara vua da Tia schdee!', '', '', '', 'Wiener Gaunersprache', 'Der Trottel postet sein Diebesgut im Fotzenbüchl – und wundert sich, warum die Kieberer vor der Tür steh’n!', '[{"kategorie": "wörtlich", "text": "\"Der Trottel postet sein Diebesgut auf Facebook – und wundert sich, warum die Bullen vor der Tür steh’n!\"  2. Der Depp stellt seine Beute auf Facebook und schaut dann blöd, wenn die Bullen Sturm läuten!  3. Der Vollidiot stellt sein Einbruchsgut auf Facebook ins Netz - und wundert sich, dass auch die Polizei online ist!"}]'::jsonb, ''),
  ('wia-covid-woa-haums-di-oone-fotznhoodan-ned-amoi-in-billa-einelossn', 'Wia Covid woa, haums di oone Fotznhoodan ned amoi in Billa einelossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wie Covid war, haben sie dich ohne Fotzenhadern nicht einmal in den Billa reingelassen!', '[{"kategorie": "wörtlich", "text": "\"Während der Covid-Epidemie durfte man ohne FFP2-Maske nicht einmal in den Supermarkt rein!\"  2. Zu Corona-Zeiten bist du ohne Atemschutzmaske nicht einmal in den Supermarkt reingekommen!  3. Während Corona bist du ohne Mund-Nasen-Schutz an der Tür zum Supermarkt gleich wieder rauskomplimentiert worden!"}]'::jsonb, ''),
  ('a-paarl-fraunkfuata', 'A Paarl Fraunkfuata!', '', '', '', 'Wiener Würstelstandjargon', 'ein Paar Frankfurter', '[{"kategorie": "", "text": "Eine Portion Frankfurter!  3. (Deutschland): Ein Paar Wiener Würstchen!"}]'::jsonb, ''),
  ('gimma-a-paarl-fraunkfuata-mid-an-gschissanan-an-buugl-und-an-sechzeenablech', 'Gimma a Paarl Fraunkfuata mid an Gschissanan, an Buugl und an Sechzeenablech!', '', '', '', 'Wiener Würstelstandjargon', 'Gib mir ein Paar Frankfurter mit einem Gschissenen, einem Buckel und einem Sechzehnerblech!', '[{"kategorie": "wörtlich", "text": "\"Gib mir ein Paar Frankfurter Würstchen mit süßem Senf, einem Brotscherzl und einer Dose Ottakringer Bier!\"  2. (Deutschland): Ich nehm zwei Wiener mit süßem Senf, einem Brotanschnitt und einer Dose Ottakringer Bier, bitte!  3. Gib mir ein Paar Frankfurter mit allem, was dazugehört: süßer Senf, ein Brotscherz’l und ein Ottakringer aus der Dose!"}]'::jsonb, 'A Paarl Fraunkfuata!'),
  ('a-fraunkfuata-bist-in-wiin-nua-so-laung-bis-di-de-kiiwara-es-easchde-moi-darwischn', 'A Fraunkfuata bist in Wiin nua so laung, bis di de Kiiwara es easchde Moi darwischn!', '', '', '', 'Wiener Gaunersprache', 'Ein Frankfurter bist du in Wien nur so lange, bis dich die Kieberer dich das erste Mal erwischen!', '[{"kategorie": "wörtlich", "text": "\"Als Nicht-Vorbestrafter giltst du in Wien nur so lange, bis dich die Bullen das erste Mal erwischen!\"  2. Nicht vorbestraft zu sein heißt: In Wien hat dich noch niemand erwischt!  3. Solange du nicht erwischt wirst, bist du in Wien unbescholten – nicht weil du’s wirklich bist, sondern weil bis jetzt keiner was bemerkt hat!"}]'::jsonb, ''),
  ('ob-sachawiaschdln-taeaewiaschdln-oda-neijoaswiaschdln-in-wiin-gibds-fiaran-jeedn-moment-a-liiblingswiaschdl', 'Ob Sachawiaschdln, Tääwiaschdln oda Neijoaswiaschdln - in Wiin gibds fiaran jeedn Moment a Liiblingswiaschdl!', '', '', '', 'Wiener Würstelstandjargon', 'Ob Sacherwürstel, Teewürstel oder Neujahrswürstchen – in Wien gibt''s für jeden Moment eine Lieblingswurst!', '[{"kategorie": "wörtlich", "text": "\"Ob Sacherwürstel, Teewürstel oder Neujahrswürstchen – Wien serviert für jede Gelegenheit die passende Wurst!\"  2. Ob Sacher-, Tee- oder Neujahrswürstel – bei uns in Wien gibt’s für jeden Anlass die richtige Wurscht!  3. Sacherwürstel, Teewürstel oder Neujahrswürstchen - für jeden Moment der perfekte Genuss, weil Wurscht in Wien eben nicht wurscht ist!"}]'::jsonb, ''),
  ('a-siassa-frotz', 'A siassa Frotz!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein süßer Fratz!', '[{"kategorie": "wörtlich", "text": "\"Ein süßer Wonnepfropfen!\"  2. Ein süßes Mäuschen!  3. Ein putziges Kerlchen!  4. Ein niedliches Zuckerpüppchen!"}]'::jsonb, ''),
  ('dem-frotzn-ghead-amoi-uandlich-da-hintan-vasoid', 'Dem Frotzn ghead amoi uandlich da Hintan vasoid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem Fratzen gehört einmal ordentlich der Hintern versohlt!', '[{"kategorie": "wörtlich", "text": "\"Dem Bengel gehört mal ordentlich der Hintern versohlt!\"  2. Dem Lausbuben sollte man mal ordentlich die Hosen strammziehen!  3. Der kleine Racker braucht mal eine Popoklatsche!"}]'::jsonb, ''),
  ('schneid-de-fritaatn-feina-sunst-schwimman-uns-wiida-teigbatzaln-in-da-suppn', 'Schneid de Fritaatn feina, sunst schwimman uns wiida Teigbatzaln in da Suppn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schneid die Frittaten feiner, sonst schwimmen uns wieder Teigbatzerln in der Suppe!', '[{"kategorie": "wörtlich", "text": "\"Schneide die Pfannkuchenstreifen feiner, sonst schwimmen uns wieder Teigklümpchen in der Suppe!\"  2. Bitte die Frittaten dünner schneiden, damit die Suppeneinlage nicht zu klumpig wird!  3. Schneide die Frittaten in dünnere Streifen, sonst haben wir wieder lauter Teigklümpchen in der Suppe schwimmen!"}]'::jsonb, ''),
  ('a-kraeftige-fritaatnsuppn-is-da-tiaeffna-zua-wiina-soeoe', 'A kräftige Fritaatnsuppn is da Tiaeffna zua Wiina Söö!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine kräftige Frittatensuppe ist der Türöffner zur Wiener Seele!', '[{"kategorie": "wörtlich", "text": "\"Eine kräftige Frittatensuppe öffnet das Wienerherz – und ein Stück weit auch das Land!\"  2. Mit jedem Löffel Frittatensuppe schmeckt man auch ein Kapitel Wiener Geschichte!  3. In einer klaren Frittatensuppe spiegelt sich die Seele der Wiener Wirtshauskultur!"}]'::jsonb, ''),
  ('mit-sein-frnak-riachda-de-kiiwara-scho-auf-hundad-meeta-entfernung', 'Mit sein Frnak riachda de Kiiwara scho auf hundad Meeta Entfernung!', '', '', '', 'Wiener Gaunersprache', 'Mit seinem Frnak riecht er die Kieberer schon auf hundert Meter Entfernung!', '[{"kategorie": "wörtlich", "text": "\"Mit seinem Riesenzinken riecht er die Bullen schon auf hundert Meter Entfernung!\"  2. Mit seinem erfahrenen Gaunernaserl riecht er die Bullen, noch bevor’s Blaulicht angeht!  3. Mit seiner riesigen Schnüffelantenne ortet er jeden Uniformierten schon auf hundert Meter Entfernung!"}]'::jsonb, ''),
  ('mit-sein-frnjak-riachda-de-kiiwara-scho-auf-hundad-meeta-entfernung', 'Mit sein Frnjak riachda de Kiiwara scho auf hundad Meeta Entfernung!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit seinem Frnjak riecht er die Kieberer schon auf hundert Meter Entfernung!', '[{"kategorie": "wörtlich", "text": "\"Mit seinem Riesenzinken riecht er die Bullen schon auf hundert Meter Entfernung!\"  2. Mit seinem erfahrenen Gaunernaserl riecht er die Bullen, noch bevor’s Blaulicht angeht!  3. Mit seiner riesigen Schnüffelantenne ortet er jeden Uniformierten schon auf hundert Meter Entfernung!"}]'::jsonb, ''),
  ('mit-sein-pfrnak-riachda-de-kiiwara-scho-auf-hundad-meeta-entfernung', 'Mit sein Pfrnak riachda de Kiiwara scho auf hundad Meeta Entfernung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit seinem Pfrnak riecht er die Kieberer schon auf hundert Meter Entfernung!', '[{"kategorie": "wörtlich", "text": "\"Mit seinem Riesenzinken riecht er die Bullen schon auf hundert Meter Entfernung!\"  2. Mit seinem erfahrenen Gaunernaserl riecht er die Bullen, noch bevor’s Blaulicht angeht!  3. Mit seiner riesigen Schnüffelantenne ortet er jeden Uniformierten schon auf hundert Meter Entfernung!"}]'::jsonb, ''),
  ('a-so-a-blaeaede-funsn', 'A so a blääde Funsn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Eine so eine blöde Funsen!', '[{"kategorie": "wörtlich", "text": "\"Was für ein eingebildetes, dummes Weibsbild!\"  2. Was für eine dumme [[Schnepfen]]!  3. Was für eine aufgeblasene Kuh!"}]'::jsonb, 'A so a blääde Schnepfn!'),
  ('fisch-gibds-in-olle-greessn-vom-winzign-schdichling-bis-zum-riisign-woihai', 'Fisch gibds in olle Greessn - vom winzign Schdichling bis zum riisign Woihai!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Fische gibt es in allen Größen – vom winzigen Stichling bis zum riesigen Walhai!', '[{"kategorie": "wörtlich", "text": "\"Es gibt Fische in allen Größen – vom winzigen Stichling bis zum riesigen Walhai!\"  2. In der Fischwelt findest du alles: winzige Minifische wie den Stichling und wahre Unterwasserriesen wie den Walhai!  3. Fische gibt’s in allen Größen – da schwimmt vom Stichling bis zum Walhai alles rum!"}]'::jsonb, ''),
  ('da-fisch-geed-auf-punkt-oiso-bleib-daneem-schdee', 'Da Fisch geed auf Punkt - oiso bleib daneem schdee!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Fisch geht auf Punkt - also bleib daneben stehn!', '[{"kategorie": "wörtlich", "text": "\"Die Garzeit für den Fisch muss genau stimmen - also bleib daneben stehen!\"  2. Beim Fisch gibt’s bei der Garzeit keinen Spielraum – also bleib dran, bis er fertig ist!  3. Fisch ist empfindlich, die Garzeit muss auf die Sekunde passen - also bleib am Herd!"}]'::jsonb, ''),
  ('glei-kriagsd-fiisch', 'Glei kriagsd Fiisch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Gleich kriegst du Fisch!', '[{"kategorie": "wörtlich", "text": "\"Gleich kriegst du Prügel!\"  2. Gleich gibt''s [[Haue]]!  3. Gleich kriegst du eins auf die Mütze!"}]'::jsonb, ''),
  ('wem-floschn', 'wem floschn', '', '', '', 'Grundwortschatz Wienerisch', 'jemanden flaschen', '[{"kategorie": "wörtlich", "text": "\"jemandem mit der flachen Hand hart ins Gesicht schlagen\"  (lautmalerisches Wort, das eine plötzliche, schallende Schlagbewegung ausdrückt, verwandt mit \"flatschen\"=\"schallend aufschlagen\")"}, {"kategorie": "allg.", "text": "jemanden kräftig ohrfeigen, [[abwatschen]], [[abfotzen]], [[dögeln]]"}, {"kategorie": "", "text": "jemandem eine [[tuschen]], [[picken]], [[paschen]], [[schnalzen]], [[schmieren]], [[reiben]], [[antauchen]]"}]'::jsonb, ''),
  ('floschn-tua-ma-nua-de-des-vadiind-haum', 'Floschn tua ma nua de, des vadiind haum!', '', '', '', 'Wiener Gaunersprache', 'Flaschen tun wir nur die, die''s verdient haben!', '[{"kategorie": "wörtlich", "text": "\"Ohrfeigen tun wir nur die, die''s verdient haben!\"  2. Ohrfeigen kriegst du bei uns nicht umsonst, die musst du dir verdient haben!  3. Wir knallen nur denen eine, die es auch verdienen!"}]'::jsonb, ''),
  ('a-so-a-floschn-hob-i-mei-leebm-laung-no-ned-gseeng', 'A so a Floschn hob I mei Leebm laung no ned gseeng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Eine solche Flasche habe ich mein Leben lang noch nicht gesehen!', '[{"kategorie": "wörtlich", "text": "\"Ein solcher Armleuchter ist mir mein Leben lang  noch nicht untergekommen!\"  2. So ein [[Dillo]] ist mir mein ganzes Leben lang noch nicht begegnet!  3. So ein Versager ist mir mein ganzes Leben nicht über den Weg gelaufen!"}]'::jsonb, ''),
  ('fleansch-ned-so-deppad-waunn-i-mit-dia-reed', 'Fleansch ned so deppad, waunn I mit dia reed!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Flensch nicht so deppert, wenn ich mit dir rede!', '[{"kategorie": "wörtlich", "text": "\"Verzieh nicht so spöttisch den Mund, wenn ich mit dir rede!\"  2. Mach nicht so ein überhebliches Gesicht, wenn ich mit dir spreche!  3. Hör auf, so blöd rumzugrinsen, wenn ich mit dir rede!"}]'::jsonb, ''),
  ('dei-deppade-fleanschn-kaunnst-da-schboan-vabockd-host-ollas-du', 'Dei deppade Fleanschn kaunnst da schboan - vabockd host ollas du!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine depperte Flenschen kannst du dir sparen - verbockt hast alles du!', '[{"kategorie": "wörtlich", "text": "\"Dein blödes Grinsen kannst du dir sparen - verbockt hast alles du!\"  2. Du brauchst deine Fresse erst gar nicht so hämisch zu verziehen – schließlich hast du alles an die Wand gefahren!  3. Spann deine Visage nicht so spöttisch auf – du bist hier der Versager!"}]'::jsonb, ''),
  ('schau-da-de-deppade-fleanschn-au-wias-mi-wiida-iwaroi-ausricht', 'Schau da de deppade Fleanschn au, wias mi wiida iwaroi ausricht!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau dir die depperte Flenschen an, wie sie mich wieder überall ausrichtet!', '[{"kategorie": "wörtlich", "text": "\"Schau dir dieses blöde grinsende Frauenzimmer an, wie sie mich wieder überall schlechtmacht!\"  2. Sieh dir diese gehässige Grins-Kuh an, wie sie mich wieder überall durch den Dreck zieht!  3. Schau sie dir an, diese dumme Lästerziege, wie sich mich hinterrücks wieder mal zerlegt!"}]'::jsonb, ''),
  ('du-grindige-vatrenzde-fleanschn', 'Du grindige, vatrenzde Fleanschn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du grindige, vertrenzte Flenschen!', '[{"kategorie": "wörtlich", "text": "\"Du ekeliges, versabbertes Lästermaul!\"  2. \"Du ungustiös trenzendes Drecksmaul!\"  3.\"Du ekelhafte, spuckende Lästerziege!\""}]'::jsonb, ''),
  ('i-gib-eam-glei-a-floschn-waunna-si-deppad-schdoeoed', 'I gib eam glei a Floschn, waunna si deppad schdööd!', '', '', '', 'Wiener Gaunersprache', 'Ich gebe ihm gleich eine Flaschen, wenn er sich deppert stellt', '[{"kategorie": "wörtlich", "text": "\"Ich verpasse ihm gleich eine Ohrfeige, wenn er sich blöd stellt!\"  2. Ich gebe ihm gleich eine [[Watsche]], wenn er weiter auf ahnungslos tut!"}, {"kategorie": "", "text": "Wenn er sich weiterhin dumm stellt, knall ich ihm gleich eine!"}]'::jsonb, ''),
  ('dea-typ-is-a-echte-floschn-dea-kriagd-nix-aufd-rei', 'Dea Typ is a echte Floschn - dea kriagd nix aufd Rei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Typ ist eine echte Flasche - der kriegt nichts auf die Reihe!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist eine echte Flasche - der kriegt nichts gebacken!\"  2. Der Typ ist ''ne totale Pfeife – der rafft gar nichts!  3. Der Typ ist ''ne Null auf ganzer Linie - der kriegt überhaupt nichts hin!"}]'::jsonb, ''),
  ('aum-sunndoog-flaniad-hoib-wiin-auf-da-prooda-hauptallee', 'Aum Sunndoog flaniad hoib Wiin auf da Prooda Hauptallee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Am Sonntag flaniert halb Wien auf der Prater Hauptallee!', '[{"kategorie": "wörtlich", "text": "\"Sonntags flaniert halb Wien auf der Prater Hauptallee!\"  2. Am Sonntag promeniert halb Wien über die Prater Hauptallee!  3. Sonntags defiliert halb Wien durch das grüne Herz des Praters!"}]'::jsonb, ''),
  ('dea-woa-so-zua-dass-eam-des-glaasl-aus-da-haund-gflutschd-is', 'Dea woa so zua, dass eam des Glaasl aus da Haund gflutschd is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der war so zu, dass ihm das Glas aus der Hand geflutscht ist!', '[{"kategorie": "wörtlich", "text": "\"Der war dermaßen besoffen, dass ihm das Glas aus der Hand gerutscht ist!\"  2. Der war so blau, dass ihm das Glas aus der Hand glitt wie ein nasser Fisch!  3. Der war so voll, dass ihm das Glas aus der Hand geschlüpft ist!"}]'::jsonb, ''),
  ('de-schdampaln-flutschn-owe-wia-oeoe', 'De Schdampaln flutschn owe wia Öö!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Stamperln flutschen runter wie Öl!', '[{"kategorie": "wörtlich", "text": "\"Die Schnäpse rutschen runter wie Öl!\"  2. Die Schnäpse gleiten wie Seide über die Zunge!  3. Die Kurzen fließen runter wie Öl!"}]'::jsonb, ''),
  ('de-schdampaln-pflutschn-owe-wiar-oeoe', 'De Schdampaln pflutschn owe wiar Öö!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Stamperln pflutschen runter wie Öl!', '[{"kategorie": "wörtlich", "text": "\"Die Schnäpse rutschen runter wie Öl!\"  2. Die Schnäpse gleiten wie Seide über die Zunge!  3. Die Kurzen fließen runter wie Öl!"}]'::jsonb, ''),
  ('de-schdampaln-fluschn-owe-wiar-oeoe', 'De Schdampaln fluschn owe wiar Öö!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Stamperln fluschen runter wie Öl!', '[{"kategorie": "wörtlich", "text": "\"Die Schnäpse rutschen runter wie Öl!\"  2. Die Schnäpse gleiten wie Seide über die Zunge!  3. Die Kurzen fließen runter wie Öl!"}]'::jsonb, ''),
  ('a-blitz-is-iwan-himmae-gflutschd-daunn-woas-auf-amoi-finsta', 'A Blitz is iwan Himmä gflutschd, daunn woas auf amoi finsta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Blitz ist über den Himmel geflutscht - dann war es auf einmal finster!', '[{"kategorie": "wörtlich", "text": "\"Ein Blitz zuckte über den Himmel – und dann war es auf einmal finster!\"  2. Ein Lichtbogen huschte über den Nachthimmel – und plötzlich war alles schwarz!  3. Ein greller Strahl flackerte kurz am Himmel auf - im nächsten Moment war alles finster!"}]'::jsonb, ''),
  ('ea-hod-de-koakn-flutschn-lossn-und-jeeda-flutscha-woara-hoch-aufs-leebm', 'Ea hod de Koakn flutschn lossn, und jeeda Flutscha woara Hoch aufs Leebm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat die Korken flutschen lassen, und jeder Flutscher war ein Hoch aufs Leben!', '[{"kategorie": "wörtlich", "text": "\"Er hat die Korken knallen lassen, und jeder Knall war ein Hoch aufs Leben!\"  2. Er hat die Korken ploppen lassen, und jeder Plopp war ein Toast aufs Leben!  3. Er hat die Korken aus der Flasche geböllert - jeder Böller ein Ja zum Jetzt!"}]'::jsonb, ''),
  ('des-flutschd', 'Des flutschd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das flutscht!', '[{"kategorie": "wörtlich", "text": "\"Läuft!\"  2. Das läuft wie am Schnürchen!\"  3. Funktioniert einwandfrei!  4. Das läuft wie geschmiert!"}]'::jsonb, ''),
  ('eigentlich-is-de-zeit-de-ma-olle-zum-leebm-haum-nuara-kuaza-flutscha', 'Eigentlich is de Zeit, de ma olle zum Leebm haum, nuara kuaza Flutscha!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Eigentlich ist die Zeit, die wir alle zum Leben haben, nur ein kurzer Flutscher!', '[{"kategorie": "wörtlich", "text": "\"Eigentlich ist die Zeit, die wir alle zum Leben haben, nur ein kurzer Wimpernschlag der Ewigkeit!\"  2. Eigentlich ist die Zeit, die wir alle zum Leben haben, nichts als ein kurzer Funkenschlag!  3. Eigentlich ist die Zeit, die wir alle zum Leben haben, nur ein blitzartiger Huscher durch Raum und Zeit!"}]'::jsonb, ''),
  ('do-hods-an-muadsdrumm-flutschara-gmochd', 'Do hods an muadsdrumm Flutschara gmochd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da hat es einen mordstrumm Flutscherer gemacht', '[{"kategorie": "", "text": "Da hat es einen Riesenknall gemacht!  2. Da hat es mächtig gekracht!  3. Da hat die Erde so richtig gebebt!"}]'::jsonb, ''),
  ('ea-trinkd-imma-nua-pfiff-owa-zum-schluss-mindastns-zeene-davoo', 'Ea trinkd imma nua Pfiff - owa zum Schluss mindastns zeene davoo!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er trinkt immer nur Pfiff - aber zum Schluss mindestens zehn davon!', '[{"kategorie": "wörtlich", "text": "\"Er trinkt immer nur Pfiff - aber am Ende braucht er mindestens zehn davon!\"  2. Er trinkt wie ein Spatz – aber mit der Ausdauer eines Kranichs!  3. Mit seinen zehn Pfiff Bier macht er am Ende mehr Meter als andere mit drei Krügerln!"}]'::jsonb, ''),
  ('ea-hod-oogleegd-owa-des-hod-eam-nix-mea-gnutzd-da-kaadi-hod-eam-trotzdem-an-frack-umghaengd', 'Ea hod oogleegd, owa des hod eam nix mea gnutzd - da Kaadi hod eam trotzdem an Frack umghängd!', '', '', '', 'Wiener Gaunersprache', 'Er hat abgelegt, aber das hat ihm nichts mehr genützt - der Richter hat ihm trotzdem einen Frack umgehängt!', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"Er hat ein volles Geständnis abgelegt, aber das hat ihm nichts mehr genützt - der Richter hat ihn trotzdem zu einer lebenslänglichen Haftstrafe verurteilt!  2. Er war voll geständig, aber das hat ihm auch nicht mehr geholfen - der Richter hat ihm trotzdem eine \"Lebenslängliche\" verpasst!  3. Er hat gesungen, aber geholfen hat’s nix - der Richter hat ihm den Lebenslatscher draufgehauen!"}]'::jsonb, ''),
  ('ea-hod-oogleegd-owa-des-hod-eam-nix-mea-gnutzd-da-kaadi-hod-eam-trotzdem-an-frack-augmessn', 'Ea hod oogleegd, owa des hod eam nix mea gnutzd - da Kaadi hod eam trotzdem an Frack augmessn!', '', '', '', 'Wiener Gaunersprache', 'Er hat abgelegt, aber das hat ihm nichts mehr genützt - der Richter hat ihm trotzdem einen Frack angemessen!', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"Er hat ein volles Geständnis abgelegt, aber das hat ihm nichts mehr genützt - der Richter hat ihn trotzdem zu einer lebenslänglichen Haftstrafe verurteilt!  2. Er war voll geständig, aber das hat ihm auch nicht mehr geholfen - der Richter hat ihm trotzdem eine \"Lebenslängliche\" verpasst!  3. Er hat gesungen, aber geholfen hat’s nix - der Richter hat ihm den Lebenslatscher draufgehauen!"}]'::jsonb, ''),
  ('is-dea-fraunk-so', 'Is dea fraunk so?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ist der frank so?', '[{"kategorie": "wörtlich", "text": "\"Ist der wirklich so?\"  2. Ist das echt sein Charakter?  3. Tickt der wirklich so?"}]'::jsonb, ''),
  ('woa-des-fraunk-so', 'Woa des fraunk so?', '', '', '', 'Wiener Sprüche, die sitzen!', 'War das frank so?', '[{"kategorie": "wörtlich", "text": "\"War das wirklich so?\"  2. Ist das tatsächlich so passiert?  3. Stimmt das wirklich?  4. Ist das wirklich wahr?"}]'::jsonb, ''),
  ('du-bist-fraunk-a-dillo', 'Du bist fraunk a Dillo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du bist fraunk a Dillo!', '[{"kategorie": "wörtlich", "text": "\"Du bist wirklich ein Idiot!\"  2. Du bist wahrhaftig ein Trottel!  3. Du bist ein richtiger Depp!"}]'::jsonb, ''),
  ('si-is-ned-fraunk-zu-dia', 'Si is ned fraunk zu dia!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie ist nicht frank zu dir!', '[{"kategorie": "wörtlich", "text": "\"Sie ist nicht ehrlich zu dir!\"  2. Sie sagt dir nicht die Wahrheit!  3. Sie ist nicht aufrichtig zu dir!  4. Sie spielt dir etwas vor!"}]'::jsonb, ''),
  ('fraunk-und-frei', 'fraunk und frei', '', '', '', 'Wiener Sprüche, die sitzen!', 'frank und frei', '[{"kategorie": "wörtlich", "text": "\"offen und ehrlich\""}, {"kategorie": "", "text": "direkt und unverblümt"}, {"kategorie": "", "text": "ohne Umschweife oder Hintergedanken"}]'::jsonb, 'Ea hod ia fraunk und frei gsoogd, dassas ned heiratn wiad!'),
  ('ea-hod-ia-fraunk-und-frei-gsoogd-dassas-ned-heiratn-wiad', 'Ea hod ia fraunk und frei gsoogd, dassas ned heiratn wiad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat ihr frank und frei gesagt, dass er sie nicht heiraten wird!', '[{"kategorie": "wörtlich", "text": "\"Er hat ihr offen und ehrlich gesagt, dass er sie nicht heiraten wird!\"  2. Er hat ihr direkt und unverblümt klargemacht, dass er sie nicht zur Frau nehmen wird!  3. Er hat ihr ohne viel Umschweife ins Gesicht gesagt, dass er sie nicht heiraten wird!"}]'::jsonb, 'fraunk und frei'),
  ('waunn-dea-fraunk-is-haass-i-lutschka', 'Waunn dea fraunk is, haass I Lutschka!', '', '', '', 'Wiener Gaunersprache', 'Wenn der frank ist, heiße ich Lutschker!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Wenn der auf freiem Fuß ist, heiße ich Lutschker!\"  2. Wenn der wirklich draußen ist, fress ich einen Besen!  3. Wenn der wirklich nicht vorbestraft ist, heiße ich Cinderella!"}]'::jsonb, ''),
  ('seita-vaheirad-is-siichst-eam-nua-no-in-fueuezboodschn-vuam-feanseea-sitzn', 'Seita vaheirad is, siichst eam nua no in Füüzboodschn vuam Feanseea sitzn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit er verheiratet ist, siehst du ihn nur noch in Filzpatschen vor dem Fernseher sitzen!', '[{"kategorie": "wörtlich", "text": "\"Seit er verheiratet ist, siehst du ihn nur noch in Filzpantoffeln vor dem Fernseher sitzen!\"  2. Kaum verheiratet, sitzt er jeden Abend nur noch vorm Fernseher – die Filzpantoffeln fest an den Füßen!  3. Seit er einen Ehering am Finger trägt, sitzt er jedes Wochenende wie festgetackert in Filzpantoffeln vor dem Fernseher!"}]'::jsonb, ''),
  ('dea-woa-amoi-a-schoafe-klingan-heit-is-a-nua-no-a-fueuezschlapfn-mid-bauchaunsotz', 'Dea woa amoi a schoafe Klingan - heit is a nua no a Füüzschlapfn mid Bauchaunsotz!', '', '', '', 'Wiener Gaunersprache', 'Der war mal ''ne scharfe Klinge – heute is er nur noch ein Filzschlapfen mit Bauchansatz!', '[{"kategorie": "wörtlich", "text": "\"Der war mal ''ne scharfe Klinge – heute is er bloß noch ’n Filzpantoffel mit Bauchansatz!\"  2. Der war mal scharf wie eine Klinge - heute trägt er Filzpantoffel und ein [[Wamperl]] vor sich her!  3. Der war mal ein Rammbock - aber heute ist aus ihm ein Filzpantoffelträger mit Wampe geworden!"}]'::jsonb, ''),
  ('wiara-de-glueuebian-wechsln-woid-hods-an-muadsflutschara-gmochd', 'Wiara de Glüübian wechsln woid, hods an Muadsflutschara gmochd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Als er die Glühbirne wechseln wollte, hat es einen Mordsflutscherer gemacht!', '[{"kategorie": "wörtlich", "text": "\"Als er die Glühbirne wechseln wollte, hat es einen Riesenknall gemacht!\"  2. Als er die neue Glühbirne reindrehen wollte, hat es mächtig gekracht!  3. Kaum hatte er die Glühbirne angefasst, gab es einen Megaknall!"}]'::jsonb, ''),
  ('warad-i-mit-ana-fut-schdott-mit-an-beidl-geboan-daed-i-a-im-sitzn-brunzn', 'Warad I mit ana Fut schdott mit an Beidl geboan, däd I a im Sitzn brunzn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wäre ich mit einer Fut statt mit einem Beidl geboren, täte ich auch im Sitzen brunzen!', '[{"kategorie": "wörtlich", "text": "\"Wäre ich mit einer Möse statt mit einem Schwanz geboren, täte ich auch im Sitzen pinkeln!\"  2. Wäre ich mit einer Muschi statt ’nem Lümmel zur Welt gekommen, würd ich auch im Sitzen pinkeln!  3. Hätt ich ’ne Möse statt ’nen Prügel, wär der Klodeckel immer unten!"}]'::jsonb, ''),
